CREATE INDEX TFPM_ADDR_ENRICH.IX_AUDIT_ENTITY
    ON TFPM_ADDR_ENRICH.AUDIT_LOG (ENTITY_TYPE, ENTITY_ID, EVENT_TIME) LOCAL;

CREATE INDEX TFPM_ADDR_ENRICH.IX_AUDIT_ACTOR
    ON TFPM_ADDR_ENRICH.AUDIT_LOG (ACTOR, EVENT_TIME) LOCAL;

COMMENT ON TABLE TFPM_ADDR_ENRICH.AUDIT_LOG IS
    'Append-only audit trail. Inserted by app code only, never by triggers.';
COMMENT ON COLUMN TFPM_ADDR_ENRICH.AUDIT_LOG.ACTOR IS
    'User principal for human actions, or "system" for automated events.';
